-- 2256 🏋️ Exercises from the book "spanish-academy-soccer-coaching-120-practices-from-the-coaches-of-real-madrid-at" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'spanish-academy-soccer-coaching-120-practices-from-the-coaches-of-real-madrid-at');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Four-station technical circuit warm-up', 'warm_up', 'opposed', NULL, 23, 23, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Warm up through free play and technique built into small competitive duels.', 'Area split into four sections: a 1v1 zone with a line to cross, a free-play zone, a 2v2 zone with two mini goals per team, and a football-tennis court with a net.', 'Groups spend 5 minutes per station and rotate: beat your man in 1v1, free juggling/ground skills, 2v2 to mini goals, then 2v2 football tennis.', 'Football tennis: one bounce or no bounce depending on age/level.', NULL, 'Try different moves to beat the defender; coach can set juggling sequences; quick accurate passing and making space in the 2v2.', 'groups of 2-4 per station', NULL, NULL, NULL, NULL, NULL, 20.0, true, false, true, NULL, 10),
  ('7v7 possession to end-zone forwards', 'small_sided_game', 'opposed', 'in_possession', 24, 24, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Team attacking and defending: passing, receiving, pressing, crossing, marking and shooting.', 'Half a full pitch with a middle zone and an end zone in front of each goal; each team has a forward waiting in the end zone, goalkeepers in goal.', '7v7 in the middle zone with free touches; teams look to find their forward in the end zone, who then finishes past the keeper.', 'Unlimited touches in the middle zone; forward has max 2 touches to score.', NULL, 'Angle the body to shield from the defender; pull your marker away to open space; look up early for the decisive pass to the forward.', '7v7 + 2 GK', 16, 16, 'half pitch', NULL, NULL, 15.0, true, true, true, NULL, 20),
  ('2v2 with wide crossers to goals', 'finishing', 'overload', 'in_possession', 25, 25, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Quick attacks, crossing and finishing.', 'Area twice the size of the penalty area with a goal at each end and a halfway line; each team has two outside players on the touchlines, one in each half.', '2v2 inside; teams work the ball to their wide player in the attacking half, who crosses for the two inside runners to volley or head in.', '2 touches.', NULL, 'Play and think fast; move into space to use the extra numbers; time the cross to the run and attack the ball.', '2v2 + 4 wide players + 2 GK', 10, 10, 'double penalty area', NULL, NULL, 20.0, true, true, true, NULL, 30),
  ('5v5 plus five support players to goals', 'small_sided_game', 'overload', 'in_possession', 26, 26, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Possession and triangular support play.', 'Quarter of a full pitch with goals and keepers at both ends; wide channels marked; five neutral players placed around and inside the area.', '5v5 with five neutrals always helping the team on the ball; build play with support angles and score in the goal.', 'Team players 2 touches; neutrals 1 touch; shots and headers 1 touch.', NULL, 'Always offer a left and right option to the receiver; lose your marker to exploit the overload; receive half-turned on the back foot.', '5v5 + 5 neutrals + 2 GK', 17, 17, 'quarter pitch', NULL, NULL, 20.0, true, true, true, NULL, 40),
  ('Heading pairs into 50/50 battle', 'technical', 'opposed', NULL, 27, 27, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Cool down while working on heading and quick reactions to loose balls.', 'Pairs facing each other at a distance suited to age/ability, each by a cone.', 'Partners head the ball back and forth; when one fails to return it and it drops, both race for it and the winner shields while the other tries to tackle.', NULL, NULL, 'Head high to give the partner time; accelerate sharply when the ball drops; use the body to protect it once won.', 'pairs', 2, NULL, NULL, NULL, NULL, 5.0, false, false, false, NULL, 50),
  ('Ball control, agility and speed stations', 'warm_up', 'passive', NULL, 32, 32, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Coordination, agility, speed and technical ball control.', 'Half a full pitch; a 40 x 30 yard square in the middle with a dribbling course of cones, a ladder and speed rings around the outside.', 'Group 1 runs the outside course: slalom with one foot (inside then outside touches), pass past the ladder and run it, slalom with the other foot, pass past the rings and hop through. Group 2: four players dribble, turn and feint inside the square and use outside players for 1-touch returns.', 'Outside players return passes first time.', 'Outside players can step in as inactive or active defenders inside the square.', 'Rotate everyone through all parts.', 'about 12-14 players', NULL, NULL, 'half pitch; centre square 40 x 30 yards', 36.6, 27.4, 15.0, false, false, false, NULL, 60),
  ('Three-section dribble, turn and pass warm-up', 'warm_up', 'unopposed', NULL, 33, 33, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Ball control, getting away from a marker, passing and awareness.', 'Lanes of three 10-yard sections with cones; players start at both ends.', 'Dribble out and cut back inside in section 1, dribble to a cone and spin 360 degrees around it in section 2, then pass to the player waiting at the far end who repeats from the other side.', NULL, NULL, 'Quick, sharp movement; sell the change of direction as escaping a marker; keep the ball close.', NULL, NULL, NULL, '3 sections of 10 yards', 27.4, NULL, 10.0, false, false, false, NULL, 70),
  ('Aerial passing and volley finishing game', 'finishing', 'overload', 'in_possession', 34, 34, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Fast attacks with aerial passes, crossing and volleys/headers.', 'Area twice the size of the penalty area with goals and keepers at each end; neutral wide players on both touchlines.', 'Two teams play with lofted passes, using the wide neutrals to cross; goals only from headers, volleys or scissor kicks. A second ball is added after 5 minutes.', 'All passes must be volleys or headers; ball may only be intercepted with the head; start with unlimited touches.', 'Add a second ball after 5 minutes.', 'Play and think quickly; move into space for the overload; check lofted pass technique; attack crosses with timed runs.', 'two teams + 4 wide neutrals + 2 GK', NULL, NULL, 'double penalty area', NULL, NULL, 15.0, true, true, true, NULL, 80),
  ('5v5 plus five one-touch possession', 'possession', 'overload', 'in_possession', 35, 35, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Passing, keeping the ball and getting free of a marker.', 'Square area with five neutral players around the edges and inside; one or two balls.', '5v5 keep-ball with the neutrals always on the side in possession; a point for a good dummy or 10 passes in a row.', 'Everyone 1 touch; ball out = throw-in; a player who loses the ball sits out for a set time.', NULL, 'Get away from your marker every pass; keep moving to use the overload; defenders press together.', '5v5 + 5 neutrals', 15, 15, NULL, NULL, NULL, 15.0, false, false, false, NULL, 90),
  ('2v1 duels into dribble-and-turn circuit', 'one_v_one', 'opposed', 'in_possession', 36, 36, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Dribbling, ball control, short passes and 2v1 duels.', 'Half a full pitch with two circuits side by side: a 2v1 zone at one end and a dribbling lane with a turning cone; two balls in play.', 'In sections 1 and 2 pairs beat a defender 2v1, then the ball carrier dribbles through cones to points 3/4; from 3 and 4 players dribble to a cone, spin 360 degrees and dribble back to 1/2.', NULL, NULL, 'Both feet and all surfaces; high tempo; sharp moves as if away from a defender.', NULL, NULL, NULL, 'half pitch', NULL, NULL, 15.0, false, false, true, NULL, 100),
  ('6v6 three-team swap-and-move game', 'small_sided_game', 'opposed', 'in_possession', 37, 37, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Passing, receiving, pressing and moving after passing or driving forward; decision making.', 'Half a full pitch with two goals and keepers; three teams of six, one waiting at the side.', '6v6; after passing a player must swap positions with a teammate; the scoring team stays on and the other is replaced by the waiting team.', 'Swap with a teammate after each pass; only 1 touch when receiving from a teammate after advancing.', NULL, 'Quick sharp movement for fast attacks; body position to protect the ball on 1 touch; defenders watch the space behind, not only the ball.', '3 teams of 6 + 2 GK', 20, 20, 'half pitch', NULL, NULL, 15.0, true, true, true, NULL, 110),
  ('5v2 keep-ball around a triangle', 'rondo', 'overload', 'in_possession', 38, 38, NULL, 'Jon Moreno Martinez (Athletic Bilbao Academy)', 'Passing, possession and player movement.', 'Square area with a cone triangle in the middle.', 'Five keep the ball from two defenders, moving around the outside of the triangle.', 'Attackers may not run or pass through the triangle.', NULL, 'Open body shape to see the next pass; keep good shape while moving into space.', '5v2', 7, 7, NULL, NULL, NULL, 10.0, false, false, false, NULL, 120),
  ('Right foot out, left foot back dribble', 'warm_up', 'unopposed', NULL, 46, 46, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Dribbling technique and ball control with each foot.', 'Lines of players behind cones set 15 yards from a turning cone.', 'Dribble out using only the right foot, round the cone, and come back using only the left foot.', 'Right foot out, left foot back.', NULL, 'Vary the dribbling technique; use laces, inside, outside and sole.', NULL, NULL, NULL, '15 yards', 13.7, NULL, 15.0, false, false, false, 'U8-U12', 130),
  ('Slalom dribble then pass into mini goal', 'technical', 'unopposed', NULL, 47, 47, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and passing accuracy.', 'Lanes with a row of slalom cones and a mini goal at the end, 15 yards from the start.', 'Dribble through the cones, then pass the ball into the mini goal; work with both feet.', 'Alternate feet through the cones.', NULL, 'Close control with knees bent, soft touches and speed; right then left foot through the cones.', NULL, NULL, NULL, '15 yards', 13.7, NULL, 15.0, true, false, true, 'U8-U12', 140),
  ('Step-on-ball shuttle relay', 'technical', 'unopposed', NULL, 48, 48, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and running with the ball with quick changes of direction.', 'Lanes with four cones 5 yards apart; one team per lane.', 'Dribble to the first cone, stop the ball under the sole and dribble back; repeat to the second, third and fourth cones as a relay.', NULL, NULL, 'Both feet, all surfaces; high intensity; turns sharp as if away from a defender.', 'teams in relay lanes', NULL, NULL, 'cones 5 yards apart', 18.3, NULL, 10.0, false, false, false, 'U8-U12', 150),
  ('Circle dribbling with pass-and-swap call', 'technical', 'unopposed', NULL, 49, 50, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Dribbling techniques, feints, moves and changes of direction.', 'Half the players stand around a circle without a ball; the other half dribble inside it; circle size by age/ability.', 'Inside players dribble, turn and feint at pace avoiding each other; on the coach''s call ''pass'' they pass to an outside player and swap places.', NULL, 'Add defenders, inactive or active depending on level.', 'Both feet; many different moves as set by the coach; sharp turns; accurate, well-paced passes; heads up and talk.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, 'U8-U12', 160),
  ('Corners to centre cone dribble and return', 'technical', 'unopposed', NULL, 51, 51, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Dribbling technique with both feet.', '20 x 20 yard square, a cone in each corner and one in the centre; a player at each corner.', 'Players dribble with one foot to the centre cone, stop the ball under the sole and return to their own corner using only the other foot.', 'One foot in, the other foot back.', NULL, 'Head up; watch for the others arriving at the middle; use all surfaces; ball tight to the feet.', '4+ players', 4, NULL, '20 x 20 yards', 18.3, 18.3, 15.0, false, false, false, 'U8-U12', 170),
  ('Diagonal corner-to-corner dribble crossing', 'technical', 'unopposed', NULL, 52, 52, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Awareness and peripheral vision while dribbling.', '20 x 20 yard square with players at each corner cone.', 'Players dribble diagonally to the opposite corner, crossing in the middle, and hand the ball to the player waiting there.', NULL, 'Start slowly and raise the speed as players get comfortable.', 'Soft touches; heads up to avoid collisions; use both feet and moves to slip past others.', '4+ players', 4, NULL, '20 x 20 yards', 18.3, 18.3, 15.0, false, false, false, 'U8-U12', 180),
  ('Dribble to centre, turn and pass back', 'technical', 'unopposed', NULL, 53, 53, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and passing accuracy.', '20 x 20 yard square, cone in the centre, players at each corner.', 'Dribble to the centre cone, stop the ball and turn back, then pass to the teammate at your starting corner, who repeats; the passer returns to the corner for the next ball.', NULL, NULL, 'Soft touches, heads up; quick tight turn; accurate pass weighted so the receiver can take it moving forward.', '4+ players', 4, NULL, '20 x 20 yards', 18.3, 18.3, 15.0, false, false, false, 'U8-U12', 190),
  ('Dribble to centre, pass right and follow', 'passing_unopposed', 'unopposed', NULL, 54, 54, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and passing on the move.', '20 x 20 yard square, cone in the centre, players at each corner.', 'Dribble to the centre using only one foot, then pass with that same foot to the corner on your right and follow the pass to take that spot.', 'Same foot for dribble and pass.', NULL, 'Soft touches, heads up; use inside and outside of the foot for the different angles; weight the pass for a forward first touch.', '8+ players', 8, NULL, '20 x 20 yards', 18.3, 18.3, 15.0, false, false, false, 'U8-U12', 200),
  ('Four-squares mini-goal shooting and switch', 'technical', 'unopposed', NULL, 55, 55, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and accurate passing/shooting.', '20 x 20 yard area with a small square in each corner holding a team of 2+ with a captain; four mini goals in the centre facing out.', 'Teams practise skills in their square; on the whistle the captain shoots at their mini goal; on ''change'' everyone dribbles to the next square.', 'First team with all players and balls into the next square wins a point.', NULL, 'Keep changing the dribbling method; rotate the captain so everyone shoots.', '4 teams of 2+', 8, NULL, '20 x 20 yards', 18.3, 18.3, 15.0, true, false, true, 'U8-U12', 210),
  ('Pole slalom, beat defender and shoot (''M'')', 'finishing', 'passive', 'in_possession', 56, 56, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Ball control and finishing.', 'Goal with keeper; from each side a course of boundary poles shaped like an M, then a defender and two coaching poles in the centre.', 'From each side a player slaloms the poles, rounds the next set, then beats the defender and shoots before reaching the centre poles; swap sides after 10 minutes.', 'Shoot before the coaching poles.', 'Defender inactive or active by level; swap sides after 10 minutes for both feet.', 'Varied dribbles and feints; sharp changes of direction with a shoulder drop; quick tempo, both feet; rotate defenders.', NULL, NULL, NULL, NULL, NULL, NULL, 20.0, true, true, true, 'U8-U12', 220),
  ('Beat two gated defenders and shoot', 'one_v_one', 'passive', 'in_possession', 57, 57, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Feints, moves and shooting technique.', 'Three stages 15 yards apart in front of a goal with keeper: two gates between poles each with a defender, then a shooting line between cones.', 'The attacker dribbles at each defender in turn using feints to get past, then shoots before reaching the cone line.', 'Shoot before the line.', 'Defenders progress from inactive to half active to fully active; run-up builds from slow to full sprint.', 'Change defenders often; practise laces, inside and outside finishes.', '1 attacker v 2 defenders + GK', 4, NULL, '3 stages 15 yards apart', 41.1, NULL, 20.0, true, true, true, 'U8-U12', 230),
  ('2v1 through two gated defenders to shot', 'one_v_one', 'overload', 'in_possession', 58, 58, NULL, 'Santiago Esposito (Atletico Madrid U11 Academy)', 'Playing a 2v1 and finishing.', 'Same three-stage layout, 15 yards apart, two gated defenders and a shooting line, goal with keeper.', 'Pairs combine with dribbles, passes and feints to get past each defender, then shoot before the cone line.', 'No offside when passing beyond the last defender; shoot before the line.', 'Drop the offside rule for younger players.', 'Keep the ball close so the pass can come early; time runs to the pass; quick one-twos; rotate defenders.', '2v1 + 2v1 + GK', 5, NULL, '3 stages 15 yards apart', 41.1, NULL, 20.0, true, true, true, 'U8-U12', 240),
  ('1v1 race past a boxed defender', 'one_v_one', 'opposed', 'in_possession', 59, 59, '1 v 1 Duel: Who will end up as number 1?', 'Santiago Esposito (Atletico Madrid U11)', 'Beat a defender with feints and moves, then finish into a mini goal.', 'Two lanes about 30 yards long, each with a defender in a coned box, two coaching poles beyond it and a mini goal at the end; attackers start with a ball on the line.', 'Attackers set off at the same time, dribble at their defender using the moves the coach names, get past before the poles and shoot into the mini goal.', 'First lane to score wins a point.', NULL, 'Keep the ball close, use feints and sharp changes of direction; rotate attackers and defenders often to keep intensity.', '1v1 in two parallel lanes', 4, NULL, '30 yards long', 27.4, NULL, 20.0, true, false, true, NULL, 250),
  ('Square diagonal and vertical passing', 'passing_unopposed', 'unopposed', 'in_possession', 60, 60, 'Diagonal and Vertical Passing Drill', 'Santiago Esposito (Atletico Madrid U11)', 'Practise down-the-line and cross-field passes.', 'Square of four cones 10-15 yards apart with players queued at each.', 'Cones 1 and 2 pass straight up to 3 and 4; those players pass diagonally across the square back to 2 and 1. Each player follows his pass to the next cone.', 'One touch where possible.', 'Add a second pair of balls (four in play).', 'Change direction so both feet are used; heads up and talk.', 'Groups at 4 cones', 8, NULL, '10-15 yards between cones', NULL, NULL, 10.0, false, false, false, NULL, 260),
  ('Square diagonal and lateral passing', 'passing_unopposed', 'unopposed', 'in_possession', 61, 61, 'Diagonal and Lateral Passing Drill', 'Santiago Esposito (Atletico Madrid U11)', 'Practise sideways and cross-field passes.', 'Square of four cones 10-15 yards apart with players queued at each.', 'Cones 1 and 2 pass across to 3 and 4; those players send it diagonally back over the square to 2 and 1. Players follow their pass.', 'One touch where possible.', 'Add two more balls (four in total).', 'Open the body and receive on the back foot; heads up and talk.', 'Groups at 4 cones', 8, NULL, '10-15 yards between cones', NULL, NULL, 10.0, false, false, false, NULL, 270),
  ('Square vertical, diagonal, horizontal passing', 'passing_unopposed', 'unopposed', 'in_possession', 62, 62, 'Vertical, Diagonal and Horizontal Passing Drill', 'Santiago Esposito (Atletico Madrid U11)', 'Combine straight, diagonal and sideways passes in one rotation.', 'Square of four cones 10-15 yards apart with players queued at each.', 'Cones 1 and 3 play up to 2 and 4 together; 2 sets it back to 1, who goes diagonally to 3; 4 plays across to 1. Players rotate 1 to 2, 2 to 3, 3 to 4, 4 to 1.', NULL, NULL, 'Come to meet the ball half-turned; open body, receive on the back foot; switch direction for both feet.', 'Groups at 4 cones', 8, NULL, '10-15 yards between cones', NULL, NULL, 10.0, false, false, false, NULL, 280),
  ('Y-shape give-and-go then dribble', 'passing_unopposed', 'unopposed', 'in_possession', 63, 64, 'Passing ''Y'' Shape (1) - Give & Go with Dribble', 'Santiago Esposito (Atletico Madrid U11)', 'Short and medium passing plus quick dribbling.', 'Y shape: cone 2 eight yards from cone 1, cones 3 and 4 20-30 yards beyond cone 2 on either side.', 'Player 1 plays into 2, gets the lay-off and passes long to 3; 3 controls and dribbles fast back to the start. Next rep goes to the other arm of the Y.', NULL, 'Limit to one touch.', 'Weight the lay-off so 1 can run onto it; time the run; both feet; heads up.', 'Groups on a Y', 4, NULL, '8 yards then 20-30 yards', NULL, NULL, 20.0, false, false, false, NULL, 290),
  ('Y-shape double one-two and long return', 'passing_unopposed', 'unopposed', 'in_possession', 65, 65, 'Passing ''Y'' Shape (2) - Give & Go with Dribble', 'Santiago Esposito (Atletico Madrid U11)', 'Short and medium range passing with well-timed runs.', 'Y shape: cone 2 eight yards from cone 1, cones 3 and 4 20-30 yards beyond.', 'Player 1 plays to 2, gets it back, returns it to 2 who has spun out; 2 dribbles quickly towards 3, who controls and plays a long ball back to 1. Players move on one position; next rep goes left.', NULL, NULL, 'After the lay-off 2 times (and if needed curves or delays) his run so the return pass lands in front of him.', 'Groups on a Y', 4, NULL, '8 yards then 20-30 yards', NULL, NULL, 20.0, false, false, false, NULL, 300),
  ('Y-shape combination with third player', 'passing_unopposed', 'unopposed', 'in_possession', 66, 66, 'Passing ''Y'' Shape (3) with Combination and Dribble', 'Santiago Esposito (Atletico Madrid U11)', 'Short and medium passing combinations at tempo.', 'Y shape: cone 2 eight yards from cone 1, cones 3 and 4 20-30 yards beyond.', 'Player 1 plays to 2 and gets it back, then plays first time to 3; 3 combines with 2 and dribbles back to the start. Repeat to the left side.', NULL, 'Move towards one touch.', 'Cut time between touch and pass; passes in front of the runner; high tempo.', 'Groups on a Y', 4, NULL, '8 yards then 20-30 yards', NULL, NULL, 20.0, false, false, false, NULL, 310),
  ('Two-touch receive pass and follow square', 'passing_unopposed', 'unopposed', 'in_possession', 67, 67, '2 Touch - Receive, Pass and Follow', 'Santiago Esposito (Atletico Madrid U11)', 'Receive and pass at different angles.', '20 x 20 yard square, 2-3 players at each corner cone and a central cone; two balls start at diagonal corners.', 'Players play vertical and diagonal passes via the centre, controlling so the next pass comes cleanly, and follow their pass to the next cone.', 'Two touches.', 'After 10 minutes reverse direction.', 'Move to meet the ball with an open body; first touch on the move; heads up and talk.', '2-3 per cone', 10, 15, '20 x 20 yards', 18.3, 18.3, 20.0, false, false, false, NULL, 320),
  ('Triangle one-two combinations with poles', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'One-Two Triangle Passing Combinations', 'Santiago Esposito (Atletico Madrid U11)', 'Short passing and the timing of runs.', 'Triangle of cones 20 yards apart, 2-3 players per cone, coaching poles near each cone.', 'Players at 1 and 3 dribble off towards 2 and 1, then the ball moves around the triangle in a set sequence of one-twos; passes go in front of the poles so the receiver controls on the run.', NULL, 'Reverse direction after 10 minutes.', 'Meet the ball; half-turned, receive and pass with the back foot; timed runs at pace; heads up.', '2-3 per cone', 6, 9, 'Cones 20 yards apart', 18.3, NULL, 20.0, false, false, false, NULL, 330),
  ('Two-touch diamond diagonal passing', 'passing_unopposed', 'unopposed', 'in_possession', 69, 69, '2 Touch Diamond Passing Drill', 'Santiago Esposito (Atletico Madrid U11)', 'Control and diagonal passing.', 'Diamond of four cones 10-15 yards apart, players at each; two balls start at points 1 and 3.', 'Players pass diagonally to the next cone; the receiver controls and passes on, then each player runs to the cone he passed to.', 'Two touches.', 'Use four balls if numbers and ability allow.', 'Meet the ball; set the body so the ball runs across it and is received and passed with the back foot.', 'Groups at 4 cones', 8, NULL, '10-15 yards between cones', NULL, NULL, 10.0, false, false, false, NULL, 340),
  ('Continuous dribble and shoot, two goals', 'finishing', 'unopposed', 'in_possession', 70, 70, 'Continuous Shooting', 'Santiago Esposito (Atletico Madrid U11)', 'Shooting technique after dribbling.', 'Two goals with keepers about 30 yards apart, coaching poles in the middle; two queues beside the goals, diagonal to each other.', 'Players dribble to the side of the central pole and shoot at the far goal; both queues work continuously. After 5 minutes switch to the other post.', NULL, NULL, 'Ball close with both feet; standing foot beside the ball, head over it, strike through it; body square to the target; use laces, inside and outside.', '2 queues + 2 GKs', 8, NULL, '30 yards between goals', 27.4, NULL, 10.0, true, true, true, NULL, 350),
  ('Continuous shooting after a pass', 'finishing', 'unopposed', 'in_possession', 71, 71, 'Continuous Shooting with Pass', 'Santiago Esposito (Atletico Madrid U11)', 'Shooting after an angled pass.', 'Two goals with keepers about 30 yards apart, coaching poles in the middle; two queues beside the goals, diagonal to each other.', 'A player passes to the opposite queue, runs off the ball to the central pole, takes a pass from the other side and shoots.', 'Maximum one control touch before shooting; first time if possible.', NULL, 'Time pass and run together; touch pushes the ball out of the feet so you can strike through the middle with head over it.', '2 queues + 2 GKs', 8, NULL, '30 yards between goals', 27.4, NULL, 10.0, true, true, true, NULL, 360),
  ('Y-shape give-and-go, first-time finish', 'finishing', 'unopposed', 'in_possession', 72, 72, 'Shooting ''Y'' Shape (1) - Pass with Give & Go', 'Santiago Esposito (Atletico Madrid U11)', 'Short and medium passing ending in a first-time shot.', 'Y shape towards a goal with keeper: cone 2 eight yards from cone 1, cones 3 and 4 20-30 yards further, either side.', 'Player 1 plays to 2, gets it back, passes to 3; 3 sets the ball for 2, who has run towards goal and shoots first time. Rotation 1 to 2, 2 to 3, 3 to 1; next rep uses the other side.', NULL, NULL, 'Short steps into the shot; anticipate when 3 will play; final pass in front of the runner.', 'Groups on a Y + GK', 5, NULL, '8 yards then 20-30 yards', NULL, NULL, 20.0, true, true, true, NULL, 370),
  ('Y-shape give-and-go, receive inside and shoot', 'finishing', 'unopposed', 'in_possession', 73, 73, 'Shooting ''Y'' Shape (2) - Pass with Give & Go', 'Santiago Esposito (Atletico Madrid U11)', 'Passing then shooting after receiving and moving with the ball.', 'Y shape towards a goal with keeper: cone 2 eight yards from cone 1, cones 3 and 4 20-30 yards further.', 'Player 1 plays to 2 and gets it back, then passes to 3; 3 takes it inside with one touch and shoots. 2 moves to 3, 1 to 2; alternate sides.', NULL, NULL, 'Receiver pushes the ball across and in front of the body towards goal with the first touch to set the shot.', 'Groups on a Y + GK', 5, NULL, '8 yards then 20-30 yards', NULL, NULL, 20.0, true, true, true, NULL, 380),
  ('Shooting wheel: round the pole and shoot', 'finishing', 'unopposed', 'in_possession', 74, 74, 'Shooting Wheel (1)', 'Santiago Esposito (Atletico Madrid U11)', 'Shooting after running onto the ball and turning in a tight space.', 'Goal with keeper; two coaching poles 20 yards out; queues at cones on the goal-line corners either side.', 'One at a time players dribble to the pole, knock the ball just past it, run round to meet it, control and shoot. Cone 1 uses the right foot, cone 2 the left; swap after 10 minutes.', NULL, 'Better players shoot first time.', 'Stay low and slow down round the pole then accelerate; weight the self-pass to the run; balance and head over the ball.', '2 queues + GK', 7, NULL, 'Poles 20 yards from goal', NULL, NULL, 20.0, true, true, true, NULL, 390),
  ('Shooting wheel: round the pole, receive, shoot', 'finishing', 'unopposed', 'in_possession', 75, 75, 'Shooting Wheel (2)', 'Santiago Esposito (Atletico Madrid U11)', 'Shooting after receiving a pass on the move.', 'Goal with keeper; two coaching poles 20 yards out; queues at cones on each goal-line corner.', 'In turn a player runs round the pole and takes a pass from the player at the opposite cone, then shoots. Cone 1 passes and shoots right-footed, cone 2 left-footed; swap after 10 minutes.', NULL, 'Better players shoot first time.', 'Stay low round the pole, slow then accelerate onto the ball; balance and head over the ball.', '2 queues + GK', 7, NULL, 'Poles 20 yards from goal', NULL, NULL, 20.0, true, true, true, NULL, 400),
  ('N-shape pass, dribble and shoot', 'finishing', 'unopposed', 'in_possession', 76, 76, 'Passing and Shooting ''N'' with Dribble and Movement', 'Santiago Esposito (Atletico Madrid U11)', 'Short passing and shooting after a forward run.', 'Three cones in an N shape in front of a goal with keeper; two coaching poles form a shooting line.', 'Player 1 passes to 2, who controls and passes to 3; 3 controls, dribbles to the poles and shoots. Rotation 1 to 2, 2 to 3, 3 collects and goes to 1. Switch to the other wing for the other foot.', NULL, NULL, 'Firm accurate passes; keep the ball close while dribbling; push it a full stride ahead with head over it before striking.', 'Groups of 3+ and GK', 4, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 410),
  ('Symmetrical passing and shooting, sideways pass', 'finishing', 'unopposed', 'in_possession', 77, 77, 'Symmetrical Passing and Shooting (1)', 'Santiago Esposito (Atletico Madrid U11)', 'Short passing then receiving and shooting after a square pass.', 'Four cones, two each side, in front of a goal with keeper; a coned shooting box marked by poles in the middle.', 'Player 1 passes to 2; 2 controls and plays across to 3, who runs onto it into the shooting box and shoots. Then the sequence starts from the other side with 4 passing to 3. Rotation 1-2-box-4 and 4-3-box-1.', NULL, 'Shoot first time.', 'One-touch receive pushing the ball in front and inside towards goal; 2''s pass well weighted; body turned to goal, head over ball.', '4 cones + GK', 5, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 420),
  ('Symmetrical passing and shooting, diagonal run', 'finishing', 'unopposed', 'in_possession', 78, 78, 'Symmetrical Passing and Shooting (2)', 'Santiago Esposito (Atletico Madrid U11)', 'Short passing and shooting after a diagonal movement.', 'Two mirror groups of three cones (1-2-3 and 4-5-6) in front of a goal with keeper and two poles.', 'Player 1 passes to 2, who controls and plays across to 3; 3 controls, dribbles to the poles and shoots left-footed, then returns to 1. Then 4, 5 and 6 do the same from the right with a right-foot finish. Swap after 10 minutes.', NULL, NULL, 'Player 2 opens his body towards the next square pass; player 3 must not set off too early.', '6+ and GK', 7, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 430),
  ('3v3 rolling waves with goalkeepers', 'small_sided_game', 'opposed', 'in_possession', 79, 79, '1 v 1 Duels in a Small Sided Game', 'Santiago Esposito (Atletico Madrid U11)', 'Team movement, pressing, passing, shooting and control in a small game.', '20 x 20 yards, goal and keeper at each end, spare teams waiting beside the goals.', 'Two teams play 3v3 aiming for quick goals. On the whistle they leave the ball where it is and two new teams come on to carry on with the score unchanged.', NULL, NULL, 'High tempo and creativity; make space to receive; receive half-turned; attack space behind defenders with feints.', '3v3 + 2 GKs, several teams', 12, NULL, '20 x 20 yards', 18.3, 18.3, 30.0, true, true, true, NULL, 440),
  ('6v6 possession with corner boxes', 'possession', 'opposed', 'in_possession', 80, 80, 'Technical Possession Game with 4 Corners', 'Santiago Esposito (Atletico Madrid U11)', 'Short passing, control and team possession against active opponents.', 'Square area with a small box in each corner; each team has two players in opposite corners.', 'Teams keep the ball and switch play from one corner to the other. A pass into a corner player means he dribbles out into the area and the passer swaps into the corner.', NULL, NULL, 'Fast accurate passes; half-turned and aware; angled support either side when a corner player has the ball; quick combinations into paths.', '6v6', 12, 12, NULL, NULL, NULL, 20.0, false, false, false, NULL, 450),
  ('Pairs ball skills and stretch warm-up', 'warm_up', 'unopposed', NULL, 86, 86, 'Individual Technique (1) - Ball Control Warm-Up', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Warm up while rehearsing individual ball skills.', '20 x 15 yards, pairs facing each other 10 yards apart, one ball per pair.', 'The player with the ball practises skills on the ground and in the air while his partner stretches; swap every 2 minutes.', NULL, NULL, NULL, 'Pairs', 2, NULL, '20 x 15 yards', 18.3, 13.7, 10.0, false, false, false, NULL, 460),
  ('Threes aerial control: head, volley, instep', 'technical', 'unopposed', NULL, 87, 87, 'Individual Technique (2) - Aerial Control', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Aerial control and passing.', '15 x 30 yards; threes with a server holding the ball in the middle and two players 5 yards away either side.', 'The server throws alternately to each outside player: high throw headed straight back, mid-height throw volleyed back, low throw controlled and returned with the instep. Rotate the server.', NULL, 'Start stationary, finish moving forward onto the ball.', 'Consistent, accurate throws.', 'Groups of 3', 3, NULL, '15 x 30 yards', 13.7, 27.4, 10.0, false, false, false, NULL, 470),
  ('Threes heading, dribbling and passing relay', 'technical', 'unopposed', NULL, 88, 88, 'Individual Technique (3) - Ball Control and Passing', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Heading, dribbling and passing/receiving technique in short high-intensity blocks.', '25 x 20 yards; threes with two on one side and one about 15 m opposite.', 'Three stations of 2-5 minutes: (1) middle player throws for the others to head back; (2) dribble to the opposite player, go round him and leave the ball for him to continue; (3) pass, control with one foot, return with the other and switch places.', NULL, NULL, 'Rotate roles in heading; full speed throughout; both feet and all surfaces.', 'Groups of 3', 3, NULL, '25 x 20 yards', 22.9, 18.3, 15.0, false, false, false, NULL, 480),
  ('Threes passing: one-touch, dummy, pass and turn', 'technical', 'unopposed', NULL, 89, 89, 'Individual Technique (4) - Passing', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing technique.', 'Half a pitch; threes in a line with one player between the other two.', 'Three 5-minute stations: (1) both outside players feed the middle man alternately and he returns first time; (2) middle man dummies a pass so it runs through to the far player, who plays it back to be dummied again; (3) middle man passes to one outside player, who plays round him and both race for it; first there plays to the other end.', 'One touch in station 1.', NULL, 'Receive half-turned on the back foot; weight the dummy pass to reach the far player; do not turn before the pass is played; high intensity.', 'Groups of 3', 3, NULL, 'Half pitch', NULL, NULL, 15.0, false, false, false, NULL, 490),
  ('Passing triangle with quick one-two', 'passing_unopposed', 'unopposed', 'in_possession', 90, 90, 'Passing Triangle (1) with Quick One-Two', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and movement to create space.', '15 x 20 yards; groups of six on a triangle of cones.', 'Players play a one-two then a pass on, dribble and pass round the triangle, receiving and passing with the same foot and following each pass to the next cone. Reverse direction for the other foot.', 'One touch depending on level.', NULL, 'Check away before coming to the ball; open body, back foot; timing keeps the ball moving; change foot often; heads up.', 'Groups of 6', 6, 6, '15 x 20 yards', 13.7, 18.3, 20.0, false, false, false, NULL, 500),
  ('Passing triangle with double one-two', 'passing_unopposed', 'unopposed', 'in_possession', 91, 91, 'Passing Triangle (2) with Double One-Two', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and movement to create space.', '15 x 20 yards; groups of six on a triangle of cones.', 'Two one-twos in sequence round the triangle, same foot to receive and pass, players following their pass. Reverse direction for the other foot.', 'One touch depending on level.', NULL, 'Open up, receive on the back foot; quick accurate passes; time the check-away and approach; switch foot often.', 'Groups of 6', 6, 6, '15 x 20 yards', 13.7, 18.3, 20.0, false, false, false, NULL, 510),
  ('Passing triangle with triple one-two', 'passing_unopposed', 'unopposed', 'in_possession', 92, 92, 'Passing Triangle (3) with Triple One-Two', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and movement to create space.', '15 x 20 yards; groups of six on a triangle of cones.', 'Three one-twos round the triangle using assist-style passes into the runner; players follow their pass and move on after their final pass. Reverse direction for both feet.', NULL, NULL, 'Pass ahead of the runner; check away open before receiving; quick accurate passes; heads up.', 'Groups of 6', 6, 6, '15 x 20 yards', 13.7, 18.3, 20.0, false, false, false, NULL, 520),
  ('Passing triangle with assists', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Passing Triangle (4) with Assists', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, assist passes and timing of runs.', '15 x 20 yards; groups of six on a triangle of cones.', 'A longer sequence of lay-offs and passes into runners round the triangle; players follow their pass and move on after their final pass. Reverse direction for both feet.', NULL, NULL, 'Receive on the move; make the run while the ball travels between the previous two players; open up and curve the run so the assist arrives in front.', 'Groups of 6', 6, 6, '15 x 20 yards', 13.7, 18.3, 20.0, false, false, false, NULL, 530),
  ('Passing square: one-two, diagonal, dribble', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Passing Square (1) with Dribble', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing and receiving.', '15 x 15 yard square; groups of eight, two per cone, one ball.', 'First player passes, gets it back and plays a diagonal pass; the receiver controls and dribbles to the teammate facing him, who passes back to the start. Players move to the next cone; work both directions.', 'Receive on the move and control with the same foot you pass with.', NULL, 'Check to make space before receiving; look up while dribbling; heads up and talk.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 540),
  ('Passing square: two one-twos and dribble', 'passing_unopposed', 'unopposed', 'in_possession', 95, 95, 'Passing Square (2) with Quick One-Two and Dribble', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and movement to create space.', '15 x 15 yard square; groups of eight, two per cone, one ball.', 'Pass and return, diagonal pass, then a second one-two before the receiver dribbles to the teammate facing him, who passes back to the start. Move on a cone; both directions.', 'Receive on the move, control with the passing foot.', NULL, 'Play the ball ahead of the runner; check away with an open body before receiving.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 550),
  ('Passing square short-long combination', 'passing_unopposed', 'unopposed', 'in_possession', 96, 96, 'Passing Square (3) with Short-Long Combination', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and support movement: short support then depth.', '15 x 15 yard square; groups of eight, two per cone.', 'A short-long pattern: after each short front-on support pass the next ball looks for depth, worked round the square in both directions; players move on after their last pass.', 'Receive on the move, control with the passing foot.', NULL, 'Check away open before receiving; fast accurate passes; do not support too early.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 560),
  ('Passing diamond: one-two and deep pass', 'passing_unopposed', 'unopposed', 'in_possession', 97, 97, 'Passing Diamond (1) - Pass + Return + Deep Pass', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing and receiving.', '15 x 15 yard diamond; groups of eight, two per cone, one ball.', 'First player plays a one-two with the next cone then a deep vertical pass across the diamond; that player controls, plays another one-two and returns the ball to the start. Move to the next cone; both directions.', 'Receive on the move, control with the passing foot.', 'Two balls; limit to one touch.', 'Check to make space; at the diagonal let the ball run across the body onto the back foot.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 570),
  ('Passing diamond: pass, control, pass', 'passing_unopposed', 'unopposed', 'in_possession', 98, 98, 'Passing Diamond (2) - Pass + Control + Pass', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing and receiving at angles.', '15 x 15 yard diamond; groups of eight, two per cone, two balls.', 'Angled passes round the diamond; each player controls and passes on with the same foot and follows his pass to the next cone. Both directions.', NULL, 'Use two balls depending on numbers and ability.', 'Check before receiving; body set so the ball crosses it to the back foot.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 580),
  ('Passing diamond quick combinations', 'passing_unopposed', 'unopposed', 'in_possession', 99, 99, 'Passing Diamond (3) with Quick Combination Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and quick combination play.', '15 x 15 yard diamond; groups of eight, two per cone.', 'Two standard options are rehearsed: a one-two after playing to the opposite player, and a deep pass to a third player after support from the fourth. Both directions; move on after your last pass.', 'Receive on the move, control with the passing foot.', NULL, 'Play the ball ahead of the runner; half-turned, back foot to receive and pass.', 'Groups of 8', 8, 8, '15 x 15 yards', 13.7, 13.7, 20.0, false, false, false, NULL, 590),
  ('Passing rectangle short and long support (11)', 'passing_unopposed', 'unopposed', 'in_possession', 100, 100, 'Passing Rectangle (1): Short and Long Support Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and support movements.', '30 x 20 yard rectangle with corner cones and inner cones; groups of 11; two balls start in opposite corners.', 'The ball keeps moving through a sequence of short and long passes with players arriving to support; rotate positions often.', NULL, NULL, 'Pass ahead of the runner and do not support too early; receive half-turned, head up; talk and eye contact.', 'Groups of 11', 11, 11, '30 x 20 yards', 27.4, 18.3, 20.0, false, false, false, NULL, 600),
  ('Passing rectangle short and long support (12)', 'passing_unopposed', 'unopposed', 'in_possession', 101, 101, 'Passing Rectangle (2): Short and Long Support', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and support movements.', '30 x 20 yard rectangle; groups of 12; two balls start in opposite corners, players at corner and inner cones.', 'Two mirrored sequences of short and long passes with support runs keep both balls moving; rotate positions often.', NULL, 'Limit to one touch to speed up play.', 'Ball and players always moving; receive half-turned, head up; talk and eye contact.', 'Groups of 12', 12, 12, '30 x 20 yards', 27.4, 18.3, 20.0, false, false, false, NULL, 610),
  ('Passing T with quick combinations', 'passing_unopposed', 'unopposed', 'in_possession', 102, 102, 'Passing ''T'' with Quick Combination Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and movement to combine quickly.', '20 x 15 yards; cones in a T shape with a central line of players and outside players.', 'The ball starts in the centre and is played with short diagonal passes out to the wide areas in a set sequence; rotate positions often.', NULL, NULL, 'Support the player facing you; check away before coming to the pass; receive half-turned, head up.', 'Groups of about 9', 8, 10, '20 x 15 yards', 18.3, 13.7, 20.0, false, false, false, NULL, 620),
  ('Short quick passing combination, two balls', 'passing_unopposed', 'unopposed', 'in_possession', 103, 103, 'Short Quick Passing Combination', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, receiving and dynamic support.', '25 x 20 yards; cone gates about 5 yards wide around the area with players at each.', 'Two balls move through diagonal and short passing combinations; each player runs quickly to where he played the ball. 8 minutes each direction.', NULL, NULL, 'Inside of the foot for short passes; high pace with two balls; check away first so one touch is possible.', '8 players', 8, 8, '25 x 20 yards', 22.9, 18.3, 15.0, false, false, false, NULL, 630),
  ('Short and long one-touch combinations', 'passing_unopposed', 'unopposed', 'in_possession', 104, 104, 'Short and Long One-Touch Combination Play (1)', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Short and long passing, combinations and timing of support runs.', '60 x 45 yards with a circuit of cones; players start from one corner queue.', 'A long pass opens a sequence of short one-touch combinations around the cones, ending with a dribble back to the start. 8 minutes each direction.', 'One touch where possible.', NULL, 'Check away before receiving; choose the right foot surface for the distance; anticipate the next move; keep ball and players moving.', 'About 9 players', 8, 10, '60 x 45 yards', 54.9, 41.1, 16.0, false, false, false, NULL, 640),
  ('Short-medium one-touch support circuit', 'passing_unopposed', 'unopposed', 'in_possession', 105, 105, 'Short and Long One-Touch Combination Play (2)', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Short and long passing, combinations and timing of support.', '40 x 30 yards; a circuit of outer and inner cones with players at each.', 'A long sequence of short and medium passes; each player runs to where he will play his second pass after supporting. 8 minutes each direction.', 'One touch where possible.', NULL, 'Check away to make space; foot surface to suit the distance; anticipate so the next pass is accurate and tight; keep moving.', 'About 10 players', 9, 11, '40 x 30 yards', 36.6, 27.4, 16.0, false, false, false, NULL, 650),
  ('One-touch inside-foot combination play', 'passing_unopposed', 'unopposed', 'in_possession', 106, 106, 'One-Touch Passing and Combination Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'One-touch passing, combinations and support timing.', '25 x 20 yards with outer corner cones and an inner square of cones.', 'A one-touch inside-of-the-foot passing sequence between the outer and inner players; each player moves in the direction of his pass. Work both sides for both feet.', 'One touch, inside of the foot.', NULL, 'Check away before receiving; suit the foot surface to the distance and anticipate the next move.', 'About 8 players', 8, 10, '25 x 20 yards', 22.9, 18.3, 10.0, false, false, false, NULL, 660),
  ('8v6+1 possession, switch halves on regain', 'transition', 'overload', 'to_attack', 107, 108, 'Possession with Attack/Defence Transition Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Team possession and fast attack/defence transitions.', '40 x 35 yards split into two halves; 8v6 plus a neutral in one half, each team keeping two players in the other half.', 'Possession is played in one half. If the defending side wins it, they play quickly to their two players in the other half and everyone moves across except the two opposing far players; whoever passes to a far player swaps with him.', 'Maximum two touches.', NULL, 'Receive half-turned for awareness and quicker decisions; defenders press as a unit: one closes the ball, the rest mark or cut passing lanes.', '8v6+1', 15, 17, '40 x 35 yards', 36.6, 32.0, 15.0, false, false, true, NULL, 670),
  ('5v5+5 possession, switch rectangles', 'positional_game', 'overload', 'in_possession', 109, 109, 'Possession, Transition Play and Interchange', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Team possession, quick transfer of play and interchange of positions.', '40 x 40 yards split into two 20 x 40 rectangles, corner squares holding utility players; five utility players in all.', '5v5 in one rectangle with the utility players joining the team on the ball. Playing into a corner square in the opposite rectangle moves everyone there; the passer swaps with that utility player.', 'Each utility player may be used at most twice per rectangle.', NULL, 'Angled support left and right when a corner player has it; quick combinations into the paths of runners.', '5v5+5', 15, 15, '40 x 40 yards', 36.6, 36.6, 20.0, false, false, true, NULL, 680),
  ('10v10 split possession with keeper link', 'possession', 'opposed', 'in_possession', 110, 110, 'Possession and Transition Game with Goalkeepers', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Passing, possession and quick switches between areas.', '40 x 30 m divided into two halves, two goalkeepers on the halfway line; 5v5 in each half.', 'Teams keep the ball in their half; after three passes they may play to a keeper, who serves the ball to their teammates in the other half, who must move to receive it. A successful switch scores a point.', 'Maximum two touches.', NULL, 'Move and pass fast; open, half-turned body to see options; defenders press as a group, one on the ball, the rest marking or blocking lanes.', '10v10 + 2 GKs', 22, 22, '40 x 30 m', 40.0, 30.0, 15.0, false, true, true, NULL, 690),
  ('Three-team 6v6+6 possession and wide play to goals', 'small_sided_game', 'overload', 'in_possession', 111, 111, 'Possession and Wide Play Small Sided Game', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Possession through the centre and wide areas ending in crosses and finishes.', 'Half a pitch split into two halves with wide channels, a goal and keeper at each end; three teams of six, the third as utility players (four wide in the channels, two inside).', 'Two teams try to go forward quickly and score. Before shooting, the team on the ball must have used at least one inside utility player (who only plays in the attacking half) and at least one wide player (who stays in his section).', 'Maximum two touches in your own half, free play in the opposition half.', NULL, 'Inside players switch quickly to the wide players; in the attacking half time runs and attack the ball on the move.', '3 teams of 6 + 2 GKs', 20, 20, 'Half pitch', NULL, NULL, 15.0, true, true, true, NULL, 700),
  ('8v8 two-zone possession with transitions', 'transition', 'overload', 'to_attack', 112, 112, 'Possession Game with Transition and Support Play', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Possession, passing, transition and support.', '50 x 30 m split into two zones; 8v8 with two side players per team and one more player per team waiting in the inactive half.', 'After 5 passes (6 at most) the team on the ball tries to find its free player in the other zone; the passer swaps with him and everyone except the side players and one per team moves across. If the ball is stolen, that team must make 5 passes on that side before switching.', 'Switch after 5 passes.', NULL, 'Talk, heads up; quick accurate passes in a tight space; open half-turned body; press as a unit; on an interception give immediate support left and right.', '8v8 + side players', 18, 20, '50 x 30 m', 50.0, 30.0, 15.0, false, false, true, NULL, 710),
  ('8v8 build-up through a central square', 'conditioned_game', 'opposed', 'in_possession', 113, 113, 'Build-Up Play from the Back in 8 v 8 SSG', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Combination play starting deep in defence.', 'Full pitch with a marked central square around the centre circle; 8v8 with keepers, two 12-minute halves.', 'Mostly free play, but teams must play through the central square to progress into the opponents half. For older players, place central midfielders in the square.', 'Must pass through the central square to progress.', NULL, 'Play quickly with 1-2 touches; get away from your marker; movement into space opens room for teammates.', '8v8 + 2 GKs', 18, 18, 'Full pitch', NULL, NULL, 24.0, true, true, true, NULL, 720),
  ('2v1 then 3v2 counter in double box', 'transition', 'overload', 'to_attack', 114, 115, '2 v 1/3 v 2: Defence to Attack Transition', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Attacking combinations with 2v1 and 3v2 overloads and defender positioning.', 'An area twice the size of the penalty box with a goal and keeper at each end; two teams of eight queued at the corners.', 'The keeper starts a 2v1 attack. If the lone defender wins the ball, two teammates join him at once for a 3v2 the other way.', NULL, NULL, 'Use quick one-twos to get behind the defender; shoot early when the chance is there; movement creates space for others.', '2 teams of 8 + 2 GKs', 18, 18, 'Double penalty area', NULL, NULL, 14.0, true, true, true, NULL, 730),
  ('6v6 with six one-touch outside players', 'small_sided_game', 'overload', 'in_possession', 116, 116, 'Numerical Advantage 12 v 6 Small Sided Game', 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Create and exploit a numerical advantage to attack fast.', 'Double penalty area with a goal and keeper at each end; two teams of six inside and six utility players around the outside.', 'The teams play to goal using the outside players for the overload. After a goal or 5 minutes the winners stay and the losers swap with the utility players.', 'Two touches inside, one touch for outside players.', NULL, 'Think and play fast; keep moving into space and use the side players; shoot when you can.', '6v6+6 + 2 GKs', 20, 20, 'Double penalty area', NULL, NULL, 20.0, true, true, true, NULL, 740),
  ('9v9 three-zone small-sided game', 'small_sided_game', 'opposed', 'in_possession', 117, 117, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Builds positional roles and responsibilities within team play.', '50 x 45 m pitch split into three zones, full goal with keeper at each end; players are tied to their zone.', '9v9 match where each side keeps its zonal shape; the attacking side may push one player forward from the zone behind into the next zone to create an overload.', 'Players must respect their zones; only one player may step up from the previous zone.', NULL, 'Fast passing and movement; pass ahead of the runner who keeps moving forward; third-man runs, overlaps and talking; defenders press together while holding zonal positions.', '9v9 inc. GKs', 18, 18, '50 x 45 metres', 50.0, 45.0, 12.0, true, true, true, 'U15', 750),
  ('2v1 then 1v2 attacking and defending duels', 'one_v_one', 'opposed', 'in_possession', 118, 119, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Rehearses attacking with a numbers advantage and with a numbers disadvantage.', 'Area about twice a penalty box with a goal and keeper at each end; three lines of players (A, B and two C lines on opposite sides) wait at the cones.', 'A passes to a C player who goes at A in a 2v1 with a team-mate from the other C line. Once the two C players reach A, a B player dribbles in from the side toward the other goal and the two C players turn defenders for a 1v2.', NULL, 'Rotate positions every 10 minutes.', 'C pair use quick one-twos to get in behind; B attacks fast with feints to get a shot away; shoot whenever it is on; in the 1v2 one defender pressures and the other covers.', '3 per line, 4 lines + 2 GKs', NULL, NULL, 'twice the penalty area', NULL, NULL, 20.0, true, true, true, 'U15', 760),
  ('Fast break attack v defence from midfield', 'transition', 'overload', 'to_attack', 120, 121, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Trains fast breaks launched from deep in midfield.', 'Two groups, each on half a pitch with a goal and keeper; a small passing square near halfway where the attackers start.', 'Group 1: attackers complete 4 passes in the square, then break into the half for 6v4 to goal. Group 2: 3 passes in the square, then 5v4 to goal.', 'Max 2 touches throughout.', 'Group 2 version is 5v4 after 3 passes (vs 6v4 after 4).', 'Use the extra man: forward runs to stretch the back line and open gaps; lose your marker to receive; use full width.', '6v4 and 5v4 + GKs', NULL, NULL, 'half pitch per group', NULL, NULL, 20.0, true, true, true, 'U15', 770),
  ('9v9 six-zone small-sided game', 'small_sided_game', 'opposed', 'in_possession', 122, 122, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Builds positional roles and responsibilities within team play.', 'Box-to-box pitch marked into six zones (central and wide channels), goal and keeper at each end.', '9v9 match played in two 7-minute halves; players may only play in the area ahead of their zone.', 'Zonal restriction on where each player may play.', NULL, 'Quick passing and movement; receive half-turned so play flows; use the wide players to advance and exploit overloads.', '9v9 inc. GKs', 18, 18, 'box to box', NULL, NULL, 14.0, true, true, true, 'U15', 780),
  ('5v5+2 neutrals+4 outside dynamic possession', 'possession', 'overload', 'in_possession', 123, 123, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Keeping the ball: passing, receiving and making space.', '45 x 40 m area; 5v5 inside plus 2 neutrals, each team has 4 support players on the outside edges.', 'Team in possession keeps the ball with the neutrals'' help; whenever a player passes to an outside team-mate they swap places with him.', '2 touches.', NULL, 'Heads up to know where team-mates are; check away with open hips before coming to receive; open the body and play with the back foot.', '5v5+2+4+4', 20, 20, '45 x 40 metres', 45.0, 40.0, 18.0, false, false, false, 'U15', 790),
  ('9v9 counter-attacking small-sided game', 'transition', 'opposed', 'to_attack', 124, 125, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Trains counter-attacks and supporting the forwards high up the pitch.', '50 x 40 m field split into two halves with small goals at the ends; play starts in one half with 9v7 while 2 players of the defending team wait in the other half.', 'When the defending team wins the ball they release it to their 2 waiting players in the other half; those two hold up, play back to arriving team-mates, then attack. The other team moves 7 across to defend, leaving 2 behind to wait.', NULL, NULL, 'Receive half-turned for quicker decisions; defending team presses as a unit (one presses the ball, others mark or cut passing lanes).', '9v9 (9v7 in a half)', 18, 18, '50 x 40 metres', 50.0, 40.0, 24.0, true, false, true, 'U15', 800),
  ('3-team 5v2 possession and transition game', 'rondo', 'overload', 'in_possession', 126, 126, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Possession, speed of play and switching roles quickly.', '40 x 30 m area: two end zones and a 3-yard central channel; three teams (5 in one end zone with 2 defenders, interceptors in the middle).', '5 keep the ball against 2 and must make 3 passes before transferring to the other zone. If the 2 fail to win it before the switch, they go into the central zone and 2 central players go across to press for a new 5v2. Central players try to intercept switches.', 'Minimum 3 passes before switching zones.', NULL, 'Change roles fast to keep it flowing; the two defenders cooperate (one presses, one cuts the pass); attackers keep moving and use the overload.', '3 teams (5v2 + central)', NULL, NULL, '40 x 30 metres', 40.0, 30.0, 15.0, false, false, false, 'U15', 810),
  ('Four-square zonal possession with neutrals', 'possession', 'overload', 'in_possession', 127, 127, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Possession with short, medium and long passing and receiving.', '50 x 50 m square split into four 25 x 25 m squares; two teams of 8 placed in pairs in each square, plus 4 neutrals, one per square; everyone stays in their square.', 'Team in possession keeps the ball across the four squares helped by the neutrals.', 'Players stay in their square; the ball may not go back to the square it just came from.', NULL, 'Keep moving, especially to receive from another zone; in the 3v2s make a triangle with supports either side of the ball.', '8v8+4', 20, 20, '50 x 50 metres', 50.0, 50.0, 15.0, false, false, false, 'U15', 820),
  ('10v10+1 wide play and switching game', 'small_sided_game', 'opposed', 'in_possession', 128, 128, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Playing out wide and switching play: interchanges, crossing and finishing.', '40 x 40 m pitch with 2-yard wide channels down each side, goals and keepers at each end, one neutral.', '10v10 plus neutral in two 12-minute halves; aim is to get the ball wide in the opposition half and switch to the far side to finish. A wide player who receives swaps places with the passer; play inside to draw opponents then go wide.', NULL, NULL, 'High tempo for switches; one touch where possible; time runs from deep to meet the cross; central players make space in front of and behind the ball.', '10v10+1 + GKs', 21, 23, '40 x 40 metres', 40.0, 40.0, 24.0, true, true, true, 'U15', 830),
  ('9v4 zonal possession and support play', 'possession', 'overload', 'in_possession', 129, 129, NULL, 'Jose A. Fernandez Lopez (Real Madrid U15)', 'Possession with short, medium and long passing and support movement.', '50 x 45 m area with two main sections and three 2 m wide channels (sides and centre); three teams of 8.', 'Two teams play in the main sections (4 per section) to keep the ball; the third team acts as utility players in the channels plus 2 more utility players inside each main section, all supporting the side in possession and passing short among themselves in the channels.', NULL, NULL, 'Keep moving to support; curved runs to lose markers; defenders talk to press together.', '3 teams of 8', 24, 24, '50 x 45 metres', 50.0, 45.0, 36.0, false, false, false, 'U15', 840),
  ('Circle dribbling to cones with options', 'technical', 'unopposed', NULL, 133, 134, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling with both feet and peripheral vision.', '40 m diameter circle with cones around the edge and a cone in the middle; players with a ball each at the edge cones.', 'Three 4-minute blocks. Free: dribble forwards and backwards, to a cone other than the one opposite, round a cone with the best turning foot, weak foot only.', NULL, 'Competition: relays to the opposite cone against other teams, weak-foot relays, relays in pairs, pairs with 2 balls. Opposition: dribble into the middle and turn back past defenders; dribble across a circle full of defenders to a cone on the far side.', 'Head up, never on the ball; avoid others heading to the middle; use laces, inside, outside and sole; ball tight to the feet.', NULL, NULL, NULL, '40 m diameter circle', 40.0, 40.0, 12.0, false, false, true, 'Youth team', 850),
  ('1v1 attack and defend two mini goals', 'one_v_one', 'opposed', 'in_possession', 135, 135, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling, feints, driving forward and attacking down the flank.', '15 x 10 m area with two 1 m cone goals at each end.', '1v1: each player attacks two mini goals and defends two; score by dribbling through the cones. Five 2-minute rounds.', 'Goal only by dribbling through a cone gate.', NULL, 'Move the ball away from where the defender tries to tackle; explode past him.', '1v1', 2, 2, '15 x 10 metres', 15.0, 10.0, 10.0, true, false, true, 'Youth team', 860),
  ('1v1 races to goal from eight lines', 'one_v_one', 'opposed', 'in_possession', 136, 136, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling, feints, driving forward and finishing.', 'Area twice a penalty box with a goal and keeper at each end; two teams in pairs at 8 numbered spots around the edges.', 'In a set order the first pair goes: attacker with the ball goes at goal and the defender reacts without leaving before the attacker. Goal-line pairs attack the far goal; side pairs can attack either goal. Next pair starts once the previous finishes. Each player gets 2 turns.', 'Defender may not set off before the attacker.', NULL, 'Attack the space behind the defender; explosive acceleration.', '2 teams in pairs + 2 GKs', NULL, NULL, 'twice the penalty area', NULL, NULL, 10.0, true, true, true, 'Youth team', 870),
  ('Aerial control and volley passing square', 'technical', 'unopposed', NULL, 137, 137, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Controlling and striking the ball in the air with good volley technique.', '10 x 10 m square with 5 markers (four corners plus a free centre marker), 4 players.', 'Middle player plays a high ball to any team-mate and runs to the free marker; the receiver plays a high ball on and moves to the free centre marker, and so on.', 'Each player starts on 10 points and loses one each time the ball drops on their watch; most points wins. Free touches, or 2-3 max by level.', 'Increase the tempo once quality is consistent.', 'Use foot, thigh, chest and head; start with slow aerial passes.', '4', 4, 4, '10 x 10 metres', 10.0, 10.0, 15.0, false, false, false, 'Youth team', 880),
  ('Passing star: pass, receive and move', 'passing_unopposed', 'unopposed', 'in_possession', 138, 138, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing with both feet; receive on one foot and pass with the other.', '40 x 40 m square, players on the four corners and four inner cones forming a star pattern.', 'Two 6-minute periods; players play the numbered sequence and follow their pass to the next position, checking off the cones before receiving as if losing a defender.', NULL, 'Progress to 1 touch where possible.', 'First touch across the body toward the next pass; speed it up with one touch.', '8+', 8, NULL, '40 x 40 metres', 40.0, 40.0, 12.0, false, false, false, 'Youth team', 890),
  ('Y-shape quick combination and dribble', 'passing_unopposed', 'unopposed', 'in_possession', 139, 139, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing and receiving with both feet in a combination.', 'Players in a Y shape about 20 m apart with a mannequin in the middle.', 'Two 6-minute periods; play the set passes (lay-off around the mannequin, wall pass, long pass) finishing with a dribble back to the start; follow your pass to the next spot.', NULL, 'Shorten the time between touch and pass, then go to 1 touch.', 'Touch out in front of the body; weight passes into the team-mate''s path; high tempo for passing and dribbling.', '5+', 4, NULL, '20 m between players', 20.0, NULL, 12.0, false, false, false, 'Youth team', 900),
  ('Two-ball 1 and 2 touch passing combinations', 'passing_unopposed', 'unopposed', 'in_possession', 140, 140, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing combinations at different angles.', 'Players on outside and inner cones around a square, about 20 m apart.', 'Two 6-minute periods; two balls start at once from opposite sides (positions 1 and 7) and run through a 12-pass sequence with lay-offs and give-and-gos; players move on after their last pass.', '1 or 2 touches.', NULL, 'Ball and players always moving; check away before receiving to make room for one touch; talk and make eye contact.', '6+', 6, NULL, '20 m between players', 20.0, NULL, 12.0, false, false, false, 'Youth team', 910),
  ('Short and long passing combination square', 'passing_unopposed', 'unopposed', 'in_possession', 141, 141, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Mixing short and long combination play.', '20 x 40 m area with a 10 x 10 m square in the middle; players at the corners and around the inner square.', 'Two 6-minute periods; corner player plays long into an inner player, a short combination follows around the inner square, then a long pass out to the next corner.', NULL, NULL, 'Inner players set the body to play whether the ball comes in front or behind; weight passes ahead of the next player; accuracy keeps it quick.', '12+', 10, NULL, '20 x 40 metres', 40.0, 20.0, 12.0, false, false, false, 'Youth team', 920),
  ('Passing combinations with two routes', 'passing_unopposed', 'unopposed', 'in_possession', 142, 142, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Combinations mixing soft and hard passes.', 'Players spread around an area about 20 m apart with one player in the middle; two balls start from opposite positions.', 'Two 6-minute periods; route A and route B run at once, both feeding the middle player from different directions; everyone except the middle player follows their pass.', NULL, NULL, 'Rotate the middle player often; middle player keeps an open stance; weight passes into the runner''s path.', '8+', 8, NULL, '20 m between players', 20.0, NULL, 12.0, false, false, false, 'Youth team', 930),
  ('Full-pitch positional build-up pattern', 'passing_unopposed', 'unopposed', 'in_possession', 143, 143, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Build-up combinations within real playing positions.', 'Full pitch, players set out in their positions with a keeper at each end.', 'Two 6-minute periods; the ball goes round the whole pitch from one keeper through the positions to the opposite keeper, using moves suited to each position. Players rotate positions; distances and passing order can be changed.', '1 or 2 touches.', 'Change distances and the order of passes to vary pass weight.', 'Open, half-turned body shape; check to make space before each pass.', 'about 16 inc. GKs', NULL, NULL, 'full pitch', NULL, NULL, 12.0, false, true, false, 'Youth team', 940),
  ('1v1 plus 2 support players to a keeper line', 'one_v_one', 'overload', 'in_possession', 144, 144, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling, control, feints and attacking down the flanks.', '15 x 20 m area; each end line is guarded by a keeper; one wall player on each sideline.', '1v1 where the attacker tries to dribble over the opposite line past the defender and the keeper, using the two side support players with one-twos. Five 2-minute periods.', 'Side support players are one touch only.', NULL, 'Quick one-twos with a side player; run in behind the defender; beat defender and keeper decisively.', '1v1+2+2 GKs', 6, 6, '15 x 20 metres', 20.0, 15.0, 10.0, false, true, true, 'Youth team', 950),
  ('Deep midfield combination and finish (1)', 'combination', 'unopposed', 'in_possession', 145, 145, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Attacking combinations from deep midfield ending with a shot.', 'Half pitch, goal and keeper; mannequins at the edge of the box and players at cones in midfield.', 'Two 8-minute periods; set passes between the midfield and front players end with the starting player running onto the final ball to shoot. Rotate roles often.', NULL, NULL, 'One touch when possible; final pass and run coordinated to receive on the move; set the ball out in front with short steps before shooting; vary laces, inside and outside.', '6+ + GK', NULL, NULL, 'half pitch', NULL, NULL, 16.0, true, true, true, 'Youth team', 960),
  ('Deep midfield combination and finish (2)', 'combination', 'unopposed', 'in_possession', 146, 146, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Attacking combinations from deep midfield ending with a timed run and shot.', 'Half pitch, goal and keeper; players set at cones around the centre circle and edge of the box.', 'Two 8-minute periods; set passes end with a player timing a run from a cone to strike at goal.', NULL, NULL, 'Final pass weighted and timed for a first-time strike; shooter checks off the cone; both feet, rotate roles, communicate.', '6+ + GK', NULL, NULL, 'half pitch', NULL, NULL, 16.0, true, true, true, 'Youth team', 970),
  ('Central combination finishing competition (1)', 'finishing', 'unopposed', 'in_possession', 147, 147, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Combinations through the centre and finishing, including headers.', 'Area twice a penalty box with a goal and keeper at each end; two teams set so both finish facing a goal, with a central player.', 'Two 8-minute periods; teams combine through the central player with an overlap and cross to finish. In the second period change the central player.', '1 point per goal, 2 for a one-touch finish.', 'Vary cross height (ground, waist, head), depth (near, middle, far post) and finish (laces, inside, outside, volleys, headers).', 'Talk to time the release on the overlap; time runs and attack the ball.', '2 teams + 2 GKs', NULL, NULL, 'twice the penalty area', NULL, NULL, 16.0, true, true, true, 'Youth team', 980),
  ('Long pass and return finishing competition (2)', 'finishing', 'unopposed', 'in_possession', 148, 148, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Playing through the centre and finishing.', 'Area twice a penalty box with goal and keeper at each end; lines of both teams beside each goal.', 'Two 8-minute periods; a player plays a long pass from one side and runs forward to meet the return and shoot. Second period swap the passing and shooting positions; players rotate to the other line of their team.', 'Competition between teams.', NULL, 'Fast, accurate passes; run timed to the pass; vary shot technique by angle; first-time finishes.', '2 teams + 2 GKs', NULL, NULL, 'twice the penalty area', NULL, NULL, 16.0, true, true, true, 'Youth team', 990),
  ('Overlap, cross and finish team competition', 'finishing', 'unopposed', 'in_possession', 149, 149, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Overlapping wing play, crossing and finishing.', 'Half pitch, goal and keeper; mannequins at the box edge; players from each team at 3 markers on each flank.', 'Two 8-minute periods; passes go out wide for an overlapping run and a cross for team-mates attacking the box. As one side crosses, the other team starts so nobody stands still; players rotate so all cross.', 'Team competition.', NULL, 'Pass wide into the overlapper''s path; cross timed to the run; one attacks near post, one far.', '2 teams + GK', NULL, NULL, 'half pitch', NULL, NULL, 16.0, true, true, true, 'Youth team', 1000),
  ('Quick interplay and third-man runs', 'passing_unopposed', 'unopposed', 'in_possession', 150, 150, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing, receiving, swapping positions and third-man runs.', 'Players around a square about 20 m apart with two inside players in the middle, each with a ball.', 'Two 6-minute periods; inside players pass to an outer player and swap places with him; a third player then moves into the middle to get the return.', NULL, NULL, 'Middle player half-turned and uses the back foot; second pass timed to the third player''s run.', '10', 8, NULL, '20 m between players', 20.0, 20.0, 12.0, false, false, false, 'Youth team', 1010),
  ('Noughts and crosses dribble relay', 'technical', 'unopposed', NULL, 151, 151, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Ball control with both feet, accurate passing and quick decisions.', '30 x 30 m square with a 3x3 grid of cones 10 m apart; two teams of 3 lined up at the side.', 'On the signal the first player of each team dribbles to a cone (not the nearest), stops there and passes back through the grid to the next team-mate, who goes next.', 'Aim is three of your team in a line (any direction) while blocking the other team; the return pass must not hit a cone.', NULL, 'Fast, accurate return pass; head up; avoid other dribblers; ball tight, use all parts of the foot.', '3v3', 6, 6, '30 x 30 metres', 30.0, 30.0, 12.0, false, false, false, 'Youth team', 1020),
  ('Noughts and crosses with 1v1 to goal', 'one_v_one', 'opposed', 'in_possession', 152, 152, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling with both feet, passing, 1v1 duels and shooting.', 'Area between both penalty boxes with the cone grid in the middle and a goal and keeper at each end.', 'As the noughts and crosses game, but when a team makes a line, its player on the ball dribbles fast at the opposition goal to shoot while the nearest player from the losing team chases to defend: a 1v1 plus keeper.', NULL, NULL, 'Head up; move the ball away from the tackle; explode; defender side-on at the right distance.', '3v3 + 2 GKs', 8, 8, 'between both penalty areas', NULL, NULL, 12.0, true, true, true, 'Youth team', 1030),
  ('4v4 zonal possession then cross and finish', 'small_sided_game', 'opposed', 'in_possession', 153, 153, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing, receiving, crossing and finishing from different areas.', '45 x 40 m area in three 15 x 40 m zones; goal and keeper at each end; 4v4 in the middle zone with a utility player on each side.', 'Three 6-minute periods; teams keep the ball in the middle; when a team brings a utility player in, they play a ball down the line and that utility player crosses into the end zone for the team that fed him to finish; the other team defends with clearances, interceptions and blocks.', '2 touches.', NULL, 'One-touch, accurate passing in the middle; cross timed to the runs; defenders side-on facing away from goal to see the cross.', '4v4+2 + 2 GKs', 12, 12, '45 x 40 metres', 45.0, 40.0, 18.0, true, true, true, 'Youth team', 1040),
  ('4v4+2 overlapping wide play and finish', 'small_sided_game', 'overload', 'in_possession', 154, 154, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing, receiving, overlaps, crossing and finishing.', 'Area twice a penalty box split into halves with wide channels; goal and keeper at each end; 2 players per team and 1 utility player in each half.', 'Four 3-minute periods; keeper plays out to a player who looks to connect with a team-mate in the other half; once that happens, the team-mate from the first half overlaps down the wing to cross for the other three to finish.', '2 players per team and 1 utility player in each half.', NULL, 'Talk to time the pass for the overlapper; cross timed to runs; defenders side-on to see the cross.', '4v4+2 + 2 GKs', 12, 12, 'twice the penalty area', NULL, NULL, 12.0, true, true, true, 'Youth team', 1050),
  ('Midfield interplay and runs into the box', 'combination', 'unopposed', 'in_possession', 155, 155, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Interplay from midfield, timing forward runs into the box, crossing and finishing.', 'Half pitch, goal and keeper; mannequins at the box edge; 3 midfield players plus outside servers near the corners and on the goal line.', 'Two 8-minute periods; the 3 midfielders combine to finish with a shot, then make runs into the box to score from balls played in from outside (first two aerial crosses from the corners, then passes from team-mates on the line). Everyone plays every position.', NULL, 'Add defenders, active or passive, by age and ability.', 'Talk when running into the box to take different spots; cross timed to the run.', '7+ + GK', NULL, NULL, 'half pitch', NULL, NULL, 16.0, true, true, true, 'Youth team', 1060),
  ('Three-team possession and awareness grid', 'possession', 'opposed', 'in_possession', 156, 156, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing, receiving, making space and awareness.', '30 x 30 m square in two halves; three colours split across the halves, one ball per colour in each half.', 'Rules change often: pass among your colour within a half; same over the whole area; pass to a different colour; then 6v3 possession in each half; then 12v6 in the whole area.', 'Control with one foot, pass with the other.', 'Five variations from unopposed passing to 6v3 and 12v6 possession.', 'Find position and angle to receive; one touch when possible; heads up to avoid other groups; open body shape to receive.', '3 teams of 6', 18, 18, '30 x 30 metres', 30.0, 30.0, 18.0, false, false, false, 'Youth team', 1070),
  ('4v4+4 possession game', 'possession', 'overload', 'in_possession', 157, 157, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Possession play, passing, receiving and making space.', '20 x 20 m area, 4v4 inside with 4 utility players on the outside.', 'Three 5-minute periods; team in possession keeps the ball with the outside players.', 'Inside max 2 touches; outside players 1 touch as if receiving with back to goal and a marker behind.', NULL, 'Think and play fast; run into space to use the overload; defenders talk to press together; react at once when the ball is lost.', '4v4+4', 12, 12, '20 x 20 metres', 20.0, 20.0, 15.0, false, false, false, 'Youth team', 1080),
  ('2v1 three-zone attacking challenge', 'one_v_one', 'overload', 'in_possession', 158, 158, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Playing 2v1, passing and dribbling through the centre.', '24 x 12 m area split into three zones, one defender per zone.', 'Two 7-minute periods; each pair works through the three zones, beating the defender in each; a defender waits on the back line of his zone until the ball enters it. Change defenders often.', 'Defenders stay in their zone and may not engage before the ball enters.', NULL, 'Dribble close so the pass can come early; runs timed to the pass; quick one-twos.', 'pairs + 3 defenders', 5, NULL, '24 x 12 metres', 24.0, 12.0, 14.0, false, false, true, 'Youth team', 1090),
  ('2v2 dribble-through mini goals game', 'one_v_one', 'opposed', 'in_possession', 159, 159, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling, passing, driving forward, wide play and defending.', '20 x 12 m area split in halves with two cone mini goals on each end line.', 'Four 3-minute periods; 2v2, each team attacks two mini goals and defends two; score by dribbling through a cone goal.', 'To score, a player must have dribbled across the attacking half first.', NULL, 'Move the ball away from the defender; explosive acceleration.', '2v2', 4, 4, '20 x 12 metres', 20.0, 12.0, 12.0, true, false, true, 'Youth team', 1100),
  ('2v1 then 2v2 attack and defence transition', 'transition', 'opposed', 'to_defend', 160, 161, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Quick switch from attack to defence plus dribbling and shooting.', 'Area twice a penalty box with goal and keeper at each end; two teams lined up at the four corners.', 'Two 8-minute periods; a 2v1 to one goal, the defender joining when the attacker touches the keeper''s pass; attackers must first play back to the team-mate on the other side. When it ends, a team-mate of the defender dribbles a new ball on for a 2v2 the other way.', 'Attackers must play the ball back to a team-mate on the far side first.', NULL, 'Fast decisions; quick switches between attacking and defending; one-twos to get behind; shoot when it is on.', '2 teams + 2 GKs', NULL, NULL, 'twice the penalty area', NULL, NULL, 16.0, true, true, true, 'Youth team', 1110),
  ('4v4 fast break to the end line', 'positional_game', 'opposed', 'in_possession', 162, 162, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Dribbling, passing, receiving and fast break attacks.', '25 x 30 m area split in halves with an end line to dribble over at each end.', 'Three 5-minute periods; 4v4, score by dribbling over the opposite line.', 'All 4 attackers must have touched the ball before a goal counts; 2 touches except when running for the line.', NULL, 'Quick sharp combinations into the space behind; make space and support; dribble away from the defender.', '4v4', 8, 8, '25 x 30 metres', 30.0, 25.0, 15.0, false, false, true, 'Youth team', 1120),
  ('11v7 fast break attacking game', 'small_sided_game', 'overload', 'in_possession', 163, 163, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Quick combination play, wide play, fast break attacks and finishing.', 'Area twice a penalty box, goal and keeper at each end; three teams of 6 and 4 utility players on the sidelines.', 'Three 8-minute periods; the attacking side (with utility players) must get a shot away before making 4 passes.', 'Shoot within 4 passes; goal from a utility player''s pass counts double; 2 touches.', NULL, 'Move into space to use the overload; check away from your marker to make room to score.', '11v7 (3 teams of 6 + 4 utilities)', 22, 22, 'twice the penalty area', NULL, NULL, 24.0, true, true, true, 'Youth team', 1130),
  ('6v6 with wide crossers attacking game', 'small_sided_game', 'opposed', 'in_possession', 164, 164, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Attacking wide play and finishing.', 'Area twice a penalty box, goal and keeper at each end; two teams of 6: 4 inside and 2 wide outside in the attacking half.', 'Three 8-minute periods; the attacking team must use one of its outside players before 4 passes, and that wide player crosses.', 'Header from a wide cross counts double; minimum 2 touches.', NULL, 'Get it wide early; wide player times the cross to the runs; curved runs to shake markers.', '6v6 + 2 GKs', 14, 14, 'twice the penalty area', NULL, NULL, 24.0, true, true, true, 'Youth team', 1140),
  ('3v3+3 three-zone possession', 'possession', 'overload', 'in_possession', 165, 165, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Control and passing, soft and hard passes with both feet, thinking before acting.', '24 x 12 m area in three zones; three teams of 3 with one player from each team in each zone, giving 2v1 in every zone.', 'Three 5-minute periods; two teams keep the ball against the third. When the defenders win it, they keep it and the team that lost it defends.', 'Players may not leave their zone; max 2 touches.', 'Limit to 1 touch to speed up play.', 'Move into space to use the 2v1; heads up to see all options.', '3 teams of 3', 9, 9, '24 x 12 metres', 24.0, 12.0, 15.0, false, false, false, 'Youth team', 1150),
  ('4v4+5 possession with wide 1v1 breakaway', 'positional_game', 'overload', 'in_possession', 166, 166, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Passing, possession and 1v1 flank play.', 'Area between the penalty areas with a 30 x 25 m centre square; pole gates on each flank.', 'Three 6-minute periods; 4v4 plus 5 utility players: defending team all 4 in the square, attacking team 2 in the square and 2 wide, plus 1 utility inside and 4 outside. After 5 passes they play a deep ball to a wide team-mate, who dribbles through the poles on his side against the opposing utility player in a 1v1.', '5 passes before the deep pass wide.', 'Make it positional: square players are central midfielders, wide players wingers, outside utilities defenders.', NULL, '4v4+5', 13, 13, 'centre square 30 x 25 metres', 30.0, 25.0, 18.0, false, false, true, 'Youth team', 1160),
  ('8v8 create and exploit space (4-touch rule)', 'possession', 'opposed', 'in_possession', 167, 167, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Creating space and exploiting it.', 'Large area between the two penalty boxes.', 'Two 10-minute periods; 8v8 possession where every receiver must take at least 4 touches before passing.', 'Minimum 4 touches on receiving.', NULL, 'Dribble into space; keep moving and lose markers with inside-out, outside-in and checked runs.', '8v8', 16, 16, 'between the 2 penalty areas', NULL, NULL, 20.0, false, false, false, 'Youth team', 1170),
  ('8v8 seven mini goals dribble game', 'conditioned_game', 'opposed', 'in_possession', 168, 168, NULL, 'Ivan Madrono Campos (Real Madrid Academy)', 'Creating space and exploiting it with dribbling.', 'Area between the two penalty boxes with 7 cone or pole mini goals: 2 per team near each end and 3 neutral across the middle.', 'Two 10-minute periods; score by dribbling through a mini goal; teams focus on attacking the 2 at the far end and defending their own 2, the middle 3 are neutral.', 'Max 2 touches except when dribbling through a goal.', NULL, 'Keep moving to lose markers (inside-out, outside-in, checked runs); use feints and moves to beat a defender to score.', '8v8', 16, 16, 'between the 2 penalty areas', NULL, NULL, 20.0, true, false, true, 'Youth team', 1180)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
